@extends('layouts.storefront')
@section('title','Product | MEETA')
@push('styles')
<style>
.product-page{padding-top:24px}.crumb{color:var(--muted);font-size:12px;margin-bottom:22px}.product-main{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(400px,.95fr);gap:52px;align-items:start}.gallery{position:sticky;top:104px}.main-image-wrap{background:#fff;border:1px solid var(--line);aspect-ratio:1/1;overflow:hidden}.main-image{width:100%;height:100%;object-fit:cover;display:block}.thumbs{display:grid;grid-template-columns:repeat(5,82px);gap:10px;margin-top:12px}.thumb{width:82px;height:82px;border:1px solid var(--line);background:#fff;padding:3px;cursor:pointer}.thumb.on{border:2px solid var(--brown)}.thumb img{width:100%;height:100%;object-fit:cover}.topline{display:flex;justify-content:space-between;align-items:center;gap:16px}.craft-badge{display:inline-flex;background:#f0dfd3;color:var(--brown);border-radius:20px;padding:7px 12px;font-size:10px;font-weight:600;letter-spacing:.7px}.rating{color:var(--brown);font-size:13px}.info h1{font:500 46px/1.12 'Playfair Display',serif;margin:20px 0 9px}.short{color:var(--muted);line-height:1.6}.price-row{display:flex;align-items:baseline;gap:12px;margin:23px 0 8px}.price{font-size:30px;color:var(--brown);font-weight:600}.mrp{text-decoration:line-through;color:var(--muted)}.saving{font-size:11px;color:#397248;background:#e5f2e8;padding:5px 8px}.tax-note{font-size:11px;color:var(--muted)}.artisan{border:1px solid var(--line);padding:16px 18px;margin:22px 0;display:flex;align-items:center;justify-content:space-between}.artisan small{display:block;color:var(--muted)}.selector{border-top:1px solid var(--line);padding-top:20px;margin-top:20px}.option-group{margin-bottom:20px}.option-label{font-weight:600;font-size:13px;margin-bottom:10px;display:flex;justify-content:space-between}.selected-label{color:var(--brown);font-weight:500}.options{display:flex;gap:9px;flex-wrap:wrap}.option{padding:11px 15px;background:#fff;border:1px solid var(--line);cursor:pointer;min-width:54px;position:relative}.option:hover:not(:disabled){border-color:var(--brown)}.option.on{border:2px solid var(--brown);color:var(--brown);padding:10px 14px;background:#fffaf6}.option:disabled{color:#aa9d96;background:#f5efeb;cursor:not-allowed;text-decoration:line-through}.variant-summary{display:flex;justify-content:space-between;gap:15px;align-items:center;background:#f8efea;padding:12px 14px;font-size:12px;margin-top:4px}.stock{color:#397248;font-weight:600}.stock.low{color:#a56618}.stock.out{color:#9b3e38}.selection-help{font-size:12px;color:#9b3e38;min-height:18px;margin-top:10px}.buy{display:grid;grid-template-columns:1fr auto;gap:10px;margin-top:10px}.buy .primary{font-size:15px}.wish{width:58px;font-size:20px;padding:0}.assurances{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--line);margin-top:18px}.assurance{text-align:center;padding:13px 6px;font-size:10px;color:var(--muted);border-right:1px solid var(--line)}.assurance:last-child{border:0}.assurance strong{display:block;color:var(--ink);font-size:11px;margin-top:3px}.details{margin-top:65px;border-top:1px solid var(--line);padding-top:42px}.details-grid{display:grid;grid-template-columns:1.3fr .7fr;gap:50px}.details h2,.reviews h2{font:500 28px 'Playfair Display',serif}.description{color:var(--muted);line-height:1.85;white-space:pre-line}.craft-story{background:#f5e7de;padding:28px}.craft-story h3{font:500 21px 'Playfair Display',serif;margin-top:0}.reviews{margin-top:40px}.review{border-top:1px solid var(--line);padding:18px 0}.loading{min-height:60vh}.fatal{padding:90px 20px;text-align:center}.fatal h2{font:500 30px 'Playfair Display',serif}
@media(max-width:900px){.product-main{grid-template-columns:1fr}.gallery{position:static}.info h1{font-size:39px}.details-grid{grid-template-columns:1fr}}@media(max-width:560px){.product-page{padding-top:14px}.product-main{gap:25px}.info h1{font-size:32px}.thumbs{grid-template-columns:repeat(4,64px)}.thumb{width:64px;height:64px}.buy{grid-template-columns:1fr 52px}.assurances{grid-template-columns:1fr}.assurance{border-right:0;border-bottom:1px solid var(--line)}}
.selector.needs-selection{border:1px solid #b64d42;background:#fff8f6;padding:16px}.buy{grid-template-columns:1fr 1fr auto}.buy-now{background:#fff}@media(max-width:560px){.buy{grid-template-columns:1fr 1fr}.wish{display:none}}
</style>
@endpush
@section('content')<main id="page" class="product-page wrap"><div class="loading">Loading handcrafted story…</div></main>@endsection
@push('scripts')
<script>
const slug=decodeURIComponent(location.pathname.split('/').pop());let product=null,selectedVariant=null,selections={};
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(v||0));const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function effective(v){return Number(v?.effective_price??v?.sale_price??v?.price??0)}
function matches(variant,choices,ignore=null){return Object.entries(choices).every(([attribute,value])=>attribute===ignore||!value||variant.attributes.some(a=>a.attribute_slug===attribute&&String(a.value_id)===String(value)))}
function resolveVariant(){const groups=product.option_groups||[],complete=groups.every(g=>selections[g.slug]);selectedVariant=complete?product.variants.find(v=>matches(v,selections))||null:null}
function optionAvailable(groupSlug,valueId){const trial={...selections,[groupSlug]:valueId};return product.variants.some(v=>v.in_stock&&matches(v,trial))}
function renderPrice(){const v=selectedVariant||product.variants.find(x=>x.in_stock)||product.variants[0],sale=effective(v),mrp=Number(v?.price||0),discount=mrp>sale?Math.round((mrp-sale)/mrp*100):0;document.getElementById('priceArea').innerHTML=`<div class="price-row"><span class="price">${money(sale)}</span>${mrp>sale?`<span class="mrp">${money(mrp)}</span><span class="saving">${discount}% off</span>`:''}</div><div class="tax-note">Inclusive of applicable taxes</div>`}
function renderSelectors(){const groups=product.option_groups||[],box=document.getElementById('selectors');if(!groups.length){selectedVariant=product.variants.find(v=>v.in_stock)||product.variants[0];box.innerHTML='';renderVariantSummary();return}box.innerHTML=groups.map(g=>`<div class="option-group"><div class="option-label"><span>Select ${esc(g.name)}</span><span class="selected-label">${esc(g.values.find(v=>String(v.id)===String(selections[g.slug]))?.value||'')}</span></div><div class="options">${g.values.map(v=>`<button type="button" class="option ${String(selections[g.slug])===String(v.id)?'on':''}" data-group="${esc(g.slug)}" data-value="${v.id}" ${optionAvailable(g.slug,v.id)?'':'disabled'}>${esc(v.value)}</button>`).join('')}</div></div>`).join('');box.querySelectorAll('.option').forEach(button=>button.onclick=()=>{selections[button.dataset.group]=Number(button.dataset.value);resolveVariant();renderSelectors();renderPrice();renderVariantSummary()});renderVariantSummary()}
function renderVariantSummary(){const box=document.getElementById('variantSummary'),help=document.getElementById('selectionHelp'),cart=document.getElementById('cartBtn');if(!selectedVariant){box.innerHTML='<span>Choose the available options to continue</span>';help.textContent='Please select all options.';cart.disabled=true;return}const qty=selectedVariant.available_quantity;box.innerHTML=`<span>SKU: ${esc(selectedVariant.sku)}</span><span class="stock ${qty<=5?'low':''}">${qty<=5?`Only ${qty} left`:`${qty} in stock`}</span>`;help.textContent='';cart.disabled=!selectedVariant.in_stock}
function render(p){product=p;selections={};if((p.option_groups||[]).length===1){const group=p.option_groups[0],available=group.values.find(value=>optionAvailable(group.slug,value.id));if(available)selections[group.slug]=available.id}resolveVariant();document.title=p.name+' | MEETA';document.getElementById('page').innerHTML=`<div class="crumb"><a href="/">Home</a> › <a href="/shop?category_id=${p.category?.id||''}">${esc(p.category?.name||'Crafts')}</a> › ${esc(p.name)}</div><section class="product-main"><div class="gallery"><div class="main-image-wrap"><img id="mainImage" class="main-image" src="${esc(p.images[0]?.url||p.image||'')}" alt="${esc(p.name)}"></div><div class="thumbs">${p.images.map((i,n)=>`<button class="thumb ${n===0?'on':''}" type="button"><img src="${esc(i.url)}" alt="${esc(i.alt_text||p.name)}"></button>`).join('')}</div></div><div class="info"><div class="topline"><span class="craft-badge">AUTHENTIC CRAFT</span><span class="rating">★ ${p.rating||'New'} (${p.reviews_count} reviews)</span></div><h1>${esc(p.name)}</h1><p class="short">${esc(p.short_description||'')}</p><div id="priceArea"></div><div class="artisan"><div><small>Crafted & fulfilled by</small><strong>${esc(p.artisan?.name||'MEETA Artisan')}</strong></div><span>›</span></div><div class="selector"><div id="selectors"></div><div class="variant-summary" id="variantSummary"></div><div class="selection-help" id="selectionHelp"></div></div><div class="buy"><button id="cartBtn" class="btn primary">Add to Cart</button><button id="wishBtn" class="btn wish" aria-label="Add to wishlist">♡</button></div><div class="assurances"><div class="assurance">◇<strong>Secure checkout</strong></div><div class="assurance">♧<strong>Artisan made</strong></div><div class="assurance">⌂<strong>All-India delivery</strong></div></div></div></section><section class="details"><div class="details-grid"><div><h2>Product details</h2><p class="description">${esc(p.description||p.short_description||'')}</p></div><aside class="craft-story"><h3>Made by hand</h3><p>Small variations in colour, weave and finish are signatures of genuine craftsmanship—not defects.</p><p>Every purchase supports independent makers and living craft traditions.</p></aside></div><div class="reviews"><h2>Customer reviews</h2>${p.reviews.length?p.reviews.map(r=>`<article class="review"><strong>★ ${r.rating} — ${esc(r.customer||'Verified buyer')}</strong><p>${esc(r.text||r.title||'')}</p></article>`).join(''):'<p class="short">No reviews yet. Be the first to share your story after delivery.</p>'}</div></section>`;bind();renderSelectors();renderPrice()}
function bind(){document.querySelectorAll('.thumb').forEach(button=>button.onclick=()=>{document.getElementById('mainImage').src=button.querySelector('img').src;document.querySelectorAll('.thumb').forEach(x=>x.classList.toggle('on',x===button))});document.getElementById('cartBtn').onclick=async()=>{if(!selectedVariant){document.getElementById('selectionHelp').textContent='Please select all options.';return}if(!requireAuth())return;try{const result=await api('/api/customer/cart/items',{method:'POST',body:JSON.stringify({product_variant_id:selectedVariant.id,quantity:1})});setCartCount(result.data.items_count);toast(`${selectedVariant.name} added to your cart`)}catch(e){toast(e.message)}};document.getElementById('wishBtn').onclick=async()=>{if(!selectedVariant){document.getElementById('selectionHelp').textContent='Please select all options first.';return}if(!requireAuth())return;try{await api('/api/customer/wishlist/items',{method:'POST',body:JSON.stringify({product_variant_id:selectedVariant.id})});toast('Saved to wishlist')}catch(e){toast(e.message)}}}
let userSelectedOptions=false;
renderSelectors=function(){const groups=product.option_groups||[],box=document.getElementById('selectors');if(!groups.length){selectedVariant=product.variants.find(v=>v.in_stock)||product.variants[0];box.innerHTML='';renderVariantSummary();return}box.innerHTML=groups.map(g=>`<div class="option-group"><div class="option-label"><span>Select ${esc(g.name)}</span><span class="selected-label">${esc(g.values.find(v=>String(v.id)===String(selections[g.slug]))?.value||'')}</span></div><div class="options">${g.values.map(v=>`<button type="button" class="option ${String(selections[g.slug])===String(v.id)?'on':''}" data-group="${esc(g.slug)}" data-value="${v.id}" ${optionAvailable(g.slug,v.id)?'':'disabled'}>${esc(v.value)}</button>`).join('')}</div></div>`).join('');box.querySelectorAll('.option').forEach(button=>button.onclick=()=>{userSelectedOptions=true;selections[button.dataset.group]=Number(button.dataset.value);resolveVariant();renderSelectors();renderPrice();renderVariantSummary()});renderVariantSummary()}
function requireSelectedVariant(){const groups=product.option_groups||[];if(selectedVariant?.in_stock&&(!groups.length||userSelectedOptions))return true;const missing=groups.filter(group=>!selections[group.slug]||(groups.length===1&&!userSelectedOptions)).map(group=>group.name);const message=missing.length?`Please select ${missing.join(' and ')} before continuing.`:'This option is unavailable. Please choose another combination.';document.getElementById('selectionHelp').textContent=message;document.querySelector('.selector')?.classList.add('needs-selection');document.querySelector('.selector')?.scrollIntoView({behavior:'smooth',block:'center'});return false}
renderVariantSummary=function(){const box=document.getElementById('variantSummary'),help=document.getElementById('selectionHelp');if(!selectedVariant){box.innerHTML='<span>Choose the available options to continue</span>';return}const qty=selectedVariant.available_quantity;box.innerHTML=`<span>SKU: ${esc(selectedVariant.sku)}</span><span class="stock ${qty<=5?'low':''}">${qty<=5?`Only ${qty} left`:`${qty} in stock`}</span>`;help.textContent='';document.querySelector('.selector')?.classList.remove('needs-selection')}
bind=function(){document.querySelectorAll('.thumb').forEach(button=>button.onclick=()=>{document.getElementById('mainImage').src=button.querySelector('img').src;document.querySelectorAll('.thumb').forEach(x=>x.classList.toggle('on',x===button))});const cart=document.getElementById('cartBtn'),buyNow=document.createElement('button');buyNow.id='buyNowBtn';buyNow.type='button';buyNow.className='btn buy-now';buyNow.textContent='Buy Now';cart.after(buyNow);cart.onclick=async()=>{if(!requireSelectedVariant()||!requireAuth())return;try{const result=await api('/api/customer/cart/items',{method:'POST',body:JSON.stringify({product_variant_id:selectedVariant.id,quantity:1})});setCartCount(result.data.items_count);const vName=selectedVariant.name||selectedVariant.attributes?.map(a=>a.value).join(' / ')||product.name;toast(`${vName} added to your cart`)}catch(e){toast(e.message)}};buyNow.onclick=()=>{if(!requireSelectedVariant()||!requireAuth())return;location.href=`/checkout?mode=buy_now&product_variant_id=${selectedVariant.id}&quantity=1`};document.getElementById('wishBtn').onclick=async()=>{if(!requireSelectedVariant())return;if(!requireAuth())return;try{await api('/api/customer/wishlist/items',{method:'POST',body:JSON.stringify({product_variant_id:selectedVariant.id})});toast('Saved to wishlist')}catch(e){toast(e.message)}}}
api('/api/customer/products/'+encodeURIComponent(slug)).then(r=>render(r.data)).catch(e=>document.getElementById('page').innerHTML=`<div class="fatal"><h2>Product unavailable</h2><p>${esc(e.message)}</p><a class="btn" href="/shop">Continue shopping</a></div>`);
</script>
@endpush
